using System;
using System.IO;
namespace Downfield {
public static class UpdateTests {
 static int failures,checks;
 static void Check(bool ok,string n){checks++;if(!ok){failures++;Console.WriteLine("FAIL Update: "+n);}}
 public static int Run(){string old=Profile.StorageOverride;string dir=Path.Combine(Path.GetTempPath(),"Downfield-update-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(dir,"club.txt");try{
 Input input=new Input();input.AimX=.85f;input.AimZ=-.7f;input.ApplyKeyboardAim();Check(input.AimX==.85f&&input.AimZ==-.7f,"idle keyboard preserves controller right stick");input.KeysDown.Add(System.Windows.Forms.Keys.Left);input.ApplyKeyboardAim();Check(input.AimX==-1&&input.AimZ==0,"keyboard arrows still control skill direction");float[] distances=new float[3];for(int rate=0;rate<3;rate++){int fps=rate==0?30:rate==1?60:120;Simulation j=new Simulation(7);j.Practice=true;j.NewGame();j.Snap();j.Handoff();for(int k=0;k<fps;k++)j.Update(1f/fps,0,0);float start=j.Controlled.X;j.SkillMove(1,0);for(int k=0;k<fps/2;k++)j.Update(1f/fps,0,1);distances[rate]=j.Controlled.X-start;Check(distances[rate]>1.7f,"visible right juke at "+fps+" FPS");}Check(Math.Abs(distances[0]-distances[2])<.25f,"juke distance consistent across frame rates");Profile p=new Profile();Roster r=new Roster();r.Sign(0,p);Check(p.Credits==9&&r.Best("QB").OVR==70,"70 OVR signing spends credits");r.Sign(0,p);Check(p.Credits==9,"duplicate signing costs nothing");r.Sign(6,p);Check(r.Best("WR")==null&&p.Credits==9,"unaffordable signing blocked");p.Credits=100;r.Sign(6,p);r.Team=1;r.Save();r=Roster.Load();Check(r.Team==1&&r.Best("WR").OVR==99,"team and 99 OVR signing survive reload");Simulation s=new Simulation(4);s.Practice=true;r.Apply(s);s.NewGame();Check(s.Receiver(0).Hands==98&&s.Receiver(0).Speed>9,"signed skills reach field");s.CyclePlay(-1);Check(s.Playbook==23&&s.RunPlay,"playbook wraps through runs");s.CyclePlay(1);Check(s.Playbook==0&&!s.RunPlay,"playbook returns to passes");Check(s.PlayNames.Length==24,"24 calls");s.Playbook=10;s.RunPlay=true;s.Snap();for(int i=0;i<12;i++)s.Update(.05f,0,0);Check(s.Controlled.Role=="RB","sweep hands off");float x=s.Controlled.X;s.SkillMove(1,0);for(int i=0;i<4;i++)s.Update(.05f,0,0);Check(s.Controlled.X>x+.5f,"right stick juke changes position");float stamina=s.Controlled.Stamina;s.SkillMove(-1,0);Check(s.Controlled.Stamina==stamina,"skill cooldown prevents repeated activation");s.Playbook=9;Check(s.RunPoint(2)[0]<0,"counter goes left");s.Playbook=10;Check(s.RunPoint(2)[0]>15,"sweep goes wide right");
 }finally{Profile.StorageOverride=old;if(Directory.Exists(dir))Directory.Delete(dir,true);}Console.WriteLine("Update: "+checks+" checks, "+failures+" failures");return failures;}
}
}
